 void RunSolarUiChecks(){int checks=0;void Check(bool value,string name){if(!value)throw new Exception("SOLAR UI FAIL: "+name);checks++;Console.WriteLine("SOLAR UI PASS: "+name);}void Click(string tip){var h=ui.Hits.LastOrDefault(h=>h.Tip==tip)??throw new Exception("Missing hit: "+tip);h.Action();}
 Check(ui.Hits.Count(h=>h.Tip.StartsWith("Space object / "))>=12,"Compact overview exposes clickable rows");Check(ui.Hits.Any(h=>h.Tip=="Warp / dock / jump / open")&&ui.Hits.Any(h=>h.Tip=="Track selected"),"Selected item has primary and tracking commands");Click("Overview / WarpTo");Check(SpaceRows().Any(r=>!r.Local)&&SpaceRows().All(r=>!r.Local||r.Kind is TargetKind.Station or TargetKind.Stargate or TargetKind.Wormhole or TargetKind.Celestial),"WarpTo tab filters navigation objects");Click("Sort overview / Name");Check(solarSort==1,"Overview sorting changes actual order");
 world.SelectedId="aster:planet:4";Click("Align to selected");Check(world.Player.Order=="align"&&world.Transit==null,"Align command sets a real flight vector");Click("Warp / dock / jump / open");Check(world.Transit?.Phase=="Aligning","Selected-item primary command starts warp");world.CancelWarp();
 var categories=CelestialMenus();Check(categories.Any(n=>n.Label=="Asteroid belts")&&categories.Single(n=>n.Label=="Moons").Children!.All(n=>n.Children!=null),"Nested categories group moons by planet");var commands=ObjectCommands("aster:gate:rook");Check(commands.Any(n=>n.Label=="Jump")&&commands.Any(n=>n.Label=="Set destination")&&commands.Any(n=>n.Label=="Warp to within"&&n.Children!.Count>=7),"Gate context exposes jump, route and warp distances");commands.Single(n=>n.Label=="Set destination").Execute!();Check(world.Waypoints.FirstOrDefault()=="rook","Context destination updates autopilot route");
 world.EnterGrid("belt",false);world.SelectedId="rock";DistanceCommands("orbit","rock").Single(n=>n.Label=="5,000 m").Execute!();Check(world.OrbitRange==5000&&world.Player.Order=="orbit","Orbit submenu changes actual helm range");
 var savedMouse=mouse;var savedOld=oldMouse;radialId="rock";radialCenter=new(800,400);radialActive=true;radialIndex=3;oldMouse=new MouseState(900,400,0,ButtonState.Pressed,ButtonState.Released,ButtonState.Released,ButtonState.Released,ButtonState.Released);mouse=new(980,400);bool consumed=SpaceInteractionInput(new MouseState(980,400,0,ButtonState.Released,ButtonState.Released,ButtonState.Released,ButtonState.Released,ButtonState.Released),new KeyboardState(),.016f);Check(consumed&&!radialActive&&world.KeepRange==20000&&world.Player.Order=="keep","Radial release applies dragged navigation distance");mouse=savedMouse;oldMouse=savedOld;
 Click("Open scanner command wheel");Check(scannerWheel&&ScannerCommands().Count==4,"Scanner wheel exposes all four connected tools");scannerWheel=false;Click("Toggle autopilot");Check(world.Autopilot,"HUD autopilot toggle controls navigation");world.Autopilot=false;world.EnterGrid("station",false);overviewTab=4;world.SelectedId="aster:planet:3";desktop.Clear();Console.WriteLine(checks+" solar UI checks passed.");}
